const sig=z=>1/(1+Math.exp(-z)),DSN={blobs:'Two clouds',overlap:'Two overlapping clouds',moons:'Two moons',circles:'Ring around a core',xor:'Checkerboard (XOR)',three:'Three clouds'};
function mkData(kind,n,noise,seed,o={}){const r=rng(seed),rn=randnFrom(r),P=[],sd=.45+.6*noise;for(let i=0;i<n;i++){let c=i%2,x,y;
  if(kind==='blobs'||kind==='overlap'){const d=kind==='overlap'?.55:1.15,rho=o.corr||0,q=Math.sqrt(1-rho*rho),s=(c?(o.sb||1):1)*sd*1.2,a=rn(),b=rn();x=(c?d:-d)+s*a;y=(c?d*.7:-d*.7)+s*(rho*a+q*b)}
  else if(kind==='moons'){const a=r()*Math.PI,j=.1+.4*noise;x=(c?.75-1.5*Math.cos(a):-.75+1.5*Math.cos(a))+j*rn();y=(c?.35-1.3*Math.sin(a):-.35+1.3*Math.sin(a))+j*rn()}
  else if(kind==='circles'){const a=r()*2*Math.PI,j=.08+.4*noise,rad=c?.75*Math.sqrt(r()):2.05+.25*rn();x=rad*Math.cos(a)+j*rn();y=rad*Math.sin(a)+j*rn()}
  else if(kind==='xor'){x=r()*5-2.5;y=r()*5-2.5;c=x*y>0?1:0;const j=.5*noise;x+=j*rn();y+=j*rn()}
  else{c=i%3;const m=[[-1.4,-.9],[1.4,-.9],[0,1.4]][c];x=m[0]+sd*rn();y=m[1]+sd*rn()}
  P.push({x:clamp(x,-2.9,2.9),y:clamp(y,-2.9,2.9),c,test:r()<.3})}return P}
function gfit(T,c){const P=T.filter(p=>p.c===c),n=Math.max(1,P.length);let mx=0,my=0;for(const p of P){mx+=p.x;my+=p.y}mx/=n;my/=n;let a=0,b=0,d=0;for(const p of P){const u=p.x-mx,v=p.y-my;a+=u*u;b+=u*v;d+=v*v}return{n:P.length,mx,my,a:a/n+1e-4,b:b/n,d:d/n+1e-4}}
const glog=(G,x,y)=>{const det=G.a*G.d-G.b*G.b,u=x-G.mx,v=y-G.my;return-.5*Math.log(det)-.5*(G.d*u*u-2*G.b*u*v+G.a*v*v)/det};
