const CLF=[
clfLesson({id:'logistic',maxWhat:'steps',steps:['Start with a random line.','For every training point, compute its score z and probability p = σ(z).','Compare p with the true label (0 for A, 1 for B). The gap p − y is the error.','Move each weight a small step against the average of error × input.','Repeat until the loss stops falling.'],tab:'Logistic regression',title:'A line that gives probabilities',ds:['blobs','overlap','moons','circles','xor'],play:'Train',stepBtn:true,S:{lr:.5,lam:0,quad:false},
 lede:'Draw a line through the plane. Far on one side the model is sure of class B, far on the other sure of class A, and near the line it is unsure. Training tilts and slides the line until the probabilities match the data.',
 capR:'Each point’s score, squashed into a probability',
 ctl:slider('logistic-lr','Learning rate η',.02,3,.02,.5)+slider('logistic-lam','Penalty on large weights λ',0,.5,.005,0)+`<label class="check" for="logistic-quad"><input type="checkbox" id="logistic-quad">Add squared features (x², xy, y²)</label>`,
 reads:rd('ll','Log loss','hl')+rd('k','Steps taken')+rd('w','Weights'),
 tryit:'Watch the line swing into place on the two clouds. Then choose the ring around a core: what accuracy can a straight line reach? Tick “Add squared features” and train again. Finally, on well-separated clouds with no penalty, watch the weights keep growing.',
 math:String.raw`<h4>Intuition</h4><p>Linear regression draws a line through the points. For classification we want a line <em>between</em> the two groups, and more than a yes or no: we want to know how sure the model is. So compute a score that says how far a point is from the line and on which side, then squash that score into a number between 0 and 1. Points far on the B side get a probability near 1, points far on the A side near 0, and points on the line exactly one half.</p>
 <h4>The model</h4>$$z=w_0+w_1x_1+w_2x_2,\qquad p=\sigma(z)=\frac{1}{1+e^{-z}}$$<p>\(z\) is the score, proportional to the signed distance from the line \(z=0\). The sigmoid \(\sigma\) is the S-shaped curve on the right. Rearranged, \(z=\ln\frac{p}{1-p}\): the model is linear in the log-odds. Each unit of \(x_1\) multiplies the odds of class B by \(e^{w_1}\).</p>
 <h4>The loss</h4><p>Choose the weights that make the observed labels most probable. The negative log of that probability, averaged, is the log loss (cross-entropy):</p>$$L(\mathbf w)=-\frac1n\sum_{i=1}^n\Big[y_i\ln p_i+(1-y_i)\ln(1-p_i)\Big]$$<p>A confident correct answer costs almost nothing. A confident wrong answer costs a great deal, and the cost grows without limit as \(p\to0\) for a true B. This is maximum likelihood under a Bernoulli model, exactly as least squares was under a Gaussian one.</p>
 <h4>The gradient</h4>$$\nabla L=\frac1n\sum_i(p_i-y_i)\,\mathbf x_i$$<p>The same form as linear regression: prediction minus target, times the input. There is no closed-form solution, so it is trained by gradient descent, but the loss is convex, so there is one minimum and descent finds it.</p>
 <h4>Three things to notice</h4><p><b>The boundary is always straight</b> in the features you give it. Adding squared features lets it draw circles and ellipses, the same trick as polynomial regression. <b>On perfectly separable data the weights grow without bound:</b> a steeper sigmoid always fits a little better, so there is no finite best. A penalty \(\lambda\lVert\mathbf w\rVert^2\) stops that. <b>The output is a probability</b>, so you can move the threshold away from 0.5 when the two kinds of mistake have different costs.</p>`,
 q:'Why not fit a straight line to the 0/1 labels with least squares instead?',a:'Its outputs are not probabilities: they run below 0 and above 1. And squared error punishes points that are very confidently correct, far from the boundary, which drags the line toward them. Log loss does not care how far beyond the boundary a correctly classified point is.',
 setup(api){const S=api.S;let w,hist,wait=0;const phi=(x,y)=>S.quad?[1,x,y,x*x,x*y,y*y]:[1,x,y];
  const reset=()=>{w=phi(0,0).map((_,j)=>j?(Math.random()-.5)*2.4:0);hist=[];wait=0};
  const loss=()=>{const T=api.train;let L=0;for(const p of T){const q=sig(dot(w,phi(p.x,p.y)));L-=p.c?Math.log(q+1e-12):Math.log(1-q+1e-12)}return L/Math.max(1,T.length)};
  const step=()=>{const T=api.train,g=w.map(()=>0);for(const p of T){const f=phi(p.x,p.y),e=sig(dot(w,f))-p.c;for(let j=0;j<w.length;j++)g[j]+=e*f[j]}for(let j=0;j<w.length;j++)w[j]-=S.lr*(g[j]/Math.max(1,T.length)+(j?S.lam*w[j]:0));hist.push(loss())};
  api.bind('lr','lr',f2,()=>{});api.bind('lam','lam',f3,()=>{});$('#logistic-quad',api.root).onchange=e=>{S.quad=e.target.checked;reset();api.redraw()};
  return{reset,p:(x,y)=>sig(dot(w,phi(x,y))),stepOnce:step,done:()=>wait>0,tick(){if(wait>0)return false;step();const n=hist.length;if(n>600||(n>30&&Math.abs(hist[n-1]-hist[n-21])<1e-5))wait=1;return true},count:()=>hist.length,
   right(t){const{g,w:cw,h}=fit(api.cr),P=plot(g,cw,h,[-8,8],[-.12,1.12],t,{xstep:2,xlabel:'score z'});g.font=MONO;g.fillStyle=t.muted;g.textAlign='right';[0,.5,1].forEach(v=>{g.strokeStyle=t.line;g.beginPath();g.moveTo(P.m.l,P.Y(v));g.lineTo(cw-P.m.r,P.Y(v));g.stroke();g.fillText(String(v),P.m.l-6,P.Y(v)+4)});clipPlot(g,P);
    for(const p of api.train){const z=clamp(dot(w,phi(p.x,p.y)),-7.9,7.9),col=p.c?t.gold:t.accent;g.strokeStyle=mix(col,col,0,.35);g.lineWidth=1;g.beginPath();g.moveTo(P.X(z),P.Y(p.c));g.lineTo(P.X(z),P.Y(sig(z)));g.stroke();g.fillStyle=col;g.beginPath();g.arc(P.X(z),P.Y(p.c),3.6,0,7);g.fill()}
    curve(g,P,sig,-8,8);g.strokeStyle=t.ink;g.lineWidth=2.6;g.stroke();g.restore();g.textAlign='left';g.fillStyle=t.muted;g.fillText('dots at their true label; line = how wrong p is',P.m.l+8,P.Y(.5)-6)},
   status(){const n=hist.length;if(!n)return'Step 0: a random starting line. Press Train or One step.';const d=n>1?hist[n-2]-hist[n-1]:0;return'Step '+n+': every weight moved against its gradient. Log loss '+(n>1?f3(hist[n-2])+' → ':'')+f3(hist[n-1])+(n>1?(d>=0?', down by '+d.toFixed(4):', UP by '+(-d).toFixed(4)+' (the step is too large)'):'')+'. The line is now '+f2(w[0])+' + '+f2(w[1])+'·x + '+f2(w[2])+'·y = 0.'+(wait>0?' The loss has stopped falling: training is finished.':'')},cur(){return wait>0?4:hist.length?3:0},
   read(set){set('ll',f3(loss()));set('k',String(hist.length));set('w',w.slice(0,3).map(f2).join(', ')+(w.length>3?' …':''))}}}}),

clfLesson({id:'softmax',maxWhat:'steps',steps:['Start with random weights, one set per class.','For every training point, compute three scores and turn them into three probabilities.','For each class, the error is its probability minus 1 if it is the true class, minus 0 otherwise.','Move each class’s weights against the average of error × input.','Repeat until the loss stops falling.'],tab:'Softmax regression',title:'More than two classes',ds:['three'],multi:true,probe:true,play:'Train',stepBtn:true,S:{lr:.5},n:150,
 lede:'With three classes, give each class its own score and turn the three scores into three probabilities that add to one. Move the pointer over the picture to read the probabilities at any spot.',
 capR:'At the pointer: one score per class, turned into probabilities',ctl:slider('softmax-lr','Learning rate η',.02,2,.02,.5),reads:rd('ll','Cross-entropy loss','hl')+rd('k','Steps taken'),
 tryit:'Move the pointer from the middle of one cloud to the spot where all three regions meet. What are the three probabilities there? Drag a point from one class deep into another class’s region and watch the loss.',
 math:String.raw`<h4>Intuition</h4><p>Logistic regression asked one question, "B or not?". With \(K\) classes, hold a small election at every point: each class gets a score from its own linear function, and the scores are turned into shares of the vote. The class with the highest score wins, and the margin of victory is the confidence.</p>
 <h4>The model</h4>$$z_k=\mathbf w_k^{\top}\mathbf x+b_k,\qquad p_k=\frac{e^{z_k}}{\sum_{j=1}^{K}e^{z_j}}$$<p>Exponentiating makes every score positive; dividing by the total makes them sum to one. This is the softmax function. Raising one score lowers every other probability. With \(K=2\) it reduces exactly to the sigmoid of the difference of the two scores.</p>
 <h4>The loss</h4>$$L=-\frac1n\sum_{i=1}^n\ln p_{i,\,y_i}$$<p>Cross-entropy: the negative log of the probability given to the correct class. Its gradient again has the familiar form, with one row per class:</p>$$\frac{\partial L}{\partial\mathbf w_k}=\frac1n\sum_i\big(p_{ik}-\mathbb 1[y_i=k]\big)\,\mathbf x_i.$$
 <h4>The boundaries</h4><p>The boundary between classes \(j\) and \(k\) is where \(z_j=z_k\), a straight line. So the plane is cut into \(K\) regions by straight edges that meet at points.</p>
 <h4>Why it matters later</h4><p>This is the last layer of nearly every neural network classifier, and of every language model, where the "classes" are the tens of thousands of possible next tokens. Dividing the scores by a temperature before the softmax sharpens or flattens the probabilities.</p>`,
 q:'Adding the same constant to all three scores changes nothing. Why?',a:'The constant multiplies the numerator and every term of the denominator by the same factor, which cancels. Only differences between scores matter. That is why one class’s weights can be fixed at zero without losing anything.',
 setup(api){const S=api.S;let W,hist,wait=0;const sm=(x,y)=>{const z=W.map(w=>w[0]+w[1]*x+w[2]*y),m=Math.max(...z),e=z.map(v=>Math.exp(v-m)),s=e[0]+e[1]+e[2];return{z,p:e.map(v=>v/s)}};
  const reset=()=>{W=[0,1,2].map(()=>[0,(Math.random()-.5)*2,(Math.random()-.5)*2]);hist=[];wait=0},loss=()=>{const T=api.train;return-T.reduce((s,p)=>s+Math.log(sm(p.x,p.y).p[p.c]+1e-12),0)/Math.max(1,T.length)};
  const step=()=>{const T=api.train,G=W.map(()=>[0,0,0]);for(const p of T){const q=sm(p.x,p.y).p;for(let k=0;k<3;k++){const e=q[k]-(p.c===k?1:0);G[k][0]+=e;G[k][1]+=e*p.x;G[k][2]+=e*p.y}}for(let k=0;k<3;k++)for(let j=0;j<3;j++)W[k][j]-=S.lr*G[k][j]/Math.max(1,T.length);hist.push(loss())};
  api.bind('lr','lr',f2,()=>{});
  return{reset,p:(x,y)=>sm(x,y).p,stepOnce:step,done:()=>wait>0,tick(){if(wait>0)return false;step();const n=hist.length;if(n>500||(n>30&&Math.abs(hist[n-1]-hist[n-21])<1e-5))wait=1;return true},count:()=>hist.length,
   overlay(g,X,Y,t){const q=api.probe;g.strokeStyle=t.ink;g.lineWidth=2.5;g.beginPath();g.arc(X(q[0]),Y(q[1]),9,0,7);g.stroke();g.beginPath();g.moveTo(X(q[0])-14,Y(q[1]));g.lineTo(X(q[0])+14,Y(q[1]));g.moveTo(X(q[0]),Y(q[1])-14);g.lineTo(X(q[0]),Y(q[1])+14);g.stroke()},
   right(t){const{g,w,h}=fit(api.cr),q=api.probe,r=sm(q[0],q[1]),cc=[t.accent,t.gold,t.ok],bw=(w-80)/3,base=h-46,top=40;g.font=MONO;g.textAlign='center';
    g.strokeStyle=t.muted;g.beginPath();g.moveTo(30,base);g.lineTo(w-20,base);g.stroke();[.5,1].forEach(v=>{g.strokeStyle=t.line;g.beginPath();g.moveTo(30,base-(base-top)*v);g.lineTo(w-20,base-(base-top)*v);g.stroke();g.fillStyle=t.muted;g.textAlign='right';g.fillText(String(v),26,base-(base-top)*v+4);g.textAlign='center'});
    r.p.forEach((v,k)=>{const x=50+k*bw;g.fillStyle=cc[k];g.fillRect(x,base-(base-top)*v,bw-22,(base-top)*v);g.fillStyle=t.ink;g.font=SANS;g.fillText((100*v).toFixed(1)+'%',x+(bw-22)/2,base-(base-top)*v-7);g.font=MONO;g.fillStyle=t.muted;g.fillText('class '+'ABC'[k],x+(bw-22)/2,base+15);g.fillText('score '+f2(r.z[k]),x+(bw-22)/2,base+30)});
    g.textAlign='left';g.fillStyle=t.muted;g.fillText('pointer at ('+f2(q[0])+', '+f2(q[1])+')',30,16)},
   status(){const n=hist.length;if(!n)return'Step 0: random weights. Press Train or One step.';return'Step '+n+': all nine weights moved against their gradients. Cross-entropy '+(n>1?f3(hist[n-2])+' → ':'')+f3(hist[n-1])+'.'+(wait>0?' The loss has stopped falling: training is finished.':'')},cur(){return wait>0?4:hist.length?3:0},
   read(set){set('ll',f3(loss()));set('k',String(hist.length))}}}}),

clfLesson({id:'knn',still:'There is nothing to train: the model is the stored training data. All the work happens when a prediction is asked for, as you can see by moving the pointer or your test point.',steps:['Store every training point. That is all the training there is.','For a new point, measure its distance to every stored point.','Pick the k closest.','Count their labels. The majority wins, and the share is the probability.'],tab:'k-nearest neighbors',title:'Ask the neighbours',ds:['moons','blobs','overlap','circles','xor'],probe:true,play:'Sweep k',S:{k:5,man:false},nc:44,
 lede:'No training at all. To classify a new point, find the k training points closest to it and take a vote. Move the pointer over the picture to see who gets a vote. Small k follows every point; large k smooths everything out.',
 capR:'Error for every k',ctl:slider('knn-k','Number of neighbours k',1,41,1,5)+`<label class="ctl" for="knn-m"><span>Distance</span><select id="knn-m"><option value="e">Straight-line (Euclidean)</option><option value="m">City-block (Manhattan)</option></select></label>`,
 reads:rd('k','k')+rd('vote','Vote at the pointer','hl')+rd('bk','k with the lowest test error'),
 tryit:'Set k = 1 and read the train accuracy. Is it a good model? Raise k slowly and watch the islands around single points disappear. What happens to the boundary, and to both errors, when k gets close to the number of points?',
 math:String.raw`<h4>Intuition</h4><p>If you want to know whether a house is in a good school district, look at the houses next to it. k-nearest neighbours makes that the whole method: things that are close together tend to share a label, so let the closest known examples vote. Nothing is learned ahead of time. The training data is kept, and all the work happens at the moment of prediction.</p>
 <h4>The rule</h4>$$\hat p(\text{B}\mid\mathbf x)=\frac1k\sum_{i\in N_k(\mathbf x)}\mathbb 1[y_i=\text{B}],\qquad \hat y=\text{the majority class in }N_k(\mathbf x)$$<p>where \(N_k(\mathbf x)\) is the set of the \(k\) training points nearest to \(\mathbf x\). It is kernel regression from the Regression module, applied to labels, with a box kernel whose width adapts to how dense the data is.</p>
 <h4>k is the bias–variance dial</h4><p>With \(k=1\) every training point owns a small territory around itself. Training error is zero, the boundary is ragged, and a single mislabelled point creates an island of wrong answers: high variance. As \(k\) grows, votes are averaged over a wider area, islands dissolve and the boundary smooths: lower variance, more bias. At \(k=n\) every point gets the same answer, the overall majority. The effective number of parameters is about \(n/k\).</p>
 <h4>Distance is a choice</h4>$$d_2(\mathbf a,\mathbf b)=\sqrt{\sum_j(a_j-b_j)^2},\qquad d_1(\mathbf a,\mathbf b)=\sum_j|a_j-b_j|$$<p>The answer depends entirely on what "near" means. A feature measured in large units dominates the distance, so features must be scaled first. And irrelevant features add noise to every distance.</p>
 <h4>Strengths and limits</h4><p>It can draw any boundary and needs no assumptions. But it must store all the data and search it for every prediction, and it suffers the curse of dimensionality directly: in many dimensions the nearest neighbours are not near.</p>`,
 q:'k = 1 gets 100% on the training data. Why is that not a reason to use it?',a:'Each training point is its own nearest neighbour, so it always votes for its own label. That measures memory, not prediction. Test accuracy, or leave-one-out accuracy, is the honest measure, and it is usually best at a moderate k.',
 setup(api){const S=api.S;let etr=[],ete=[],dir=1,fr=0,ks;const dist=(p,x,y)=>S.man?Math.abs(p.x-x)+Math.abs(p.y-y):Math.hypot(p.x-x,p.y-y);
  const near=(x,y,k)=>{const d=api.train.map(p=>[dist(p,x,y),p]);d.sort((a,b)=>a[0]-b[0]);return d.slice(0,k)};
  const fitc=()=>{const T=api.train,KM=Math.min(41,T.length);etr=[];ete=[];const run=(P,E)=>{const cnt=new Array(KM+1).fill(0);for(const p of P){const d=T.map(q=>[dist(q,p.x,p.y),q.c]);d.sort((a,b)=>a[0]-b[0]);let s=0;for(let k=1;k<=KM;k++){s+=d[k-1][1];if((s/k>=.5?1:0)!==p.c)cnt[k]++}}for(let k=1;k<=KM;k++)E[k]=P.length?cnt[k]/P.length:NaN};run(T,etr);run(api.test,ete)};
  ks=api.bind('k','k',v=>String(v),()=>api.redraw());$('#knn-m',api.root).onchange=e=>{S.man=e.target.value==='m';fitc();api.redraw()};
  return{fit:fitc,p:(x,y)=>{const nb=near(x,y,S.k);return nb.reduce((s,q)=>s+q[1].c,0)/Math.max(1,nb.length)},tick(){if(++fr%26)return false;let k=S.k+dir*2;if(k>41){dir=-1;k=39}if(k<1){dir=1;k=3}S.k=k;ks.set(k);return true},
   overlay(g,X,Y,t,w){const q=api.probe,nb=near(q[0],q[1],S.k),rad=nb.length?nb[nb.length-1][0]:0,s=w/6;g.strokeStyle=t.ink;g.lineWidth=1.6;g.beginPath();if(S.man){g.moveTo(X(q[0])+rad*s,Y(q[1]));g.lineTo(X(q[0]),Y(q[1])-rad*s);g.lineTo(X(q[0])-rad*s,Y(q[1]));g.lineTo(X(q[0]),Y(q[1])+rad*s);g.closePath()}else g.arc(X(q[0]),Y(q[1]),rad*s,0,7);g.stroke();
    g.lineWidth=1;for(const n of nb){g.beginPath();g.moveTo(X(q[0]),Y(q[1]));g.lineTo(X(n[1].x),Y(n[1].y));g.stroke()}g.fillStyle=t.ink;g.beginPath();g.arc(X(q[0]),Y(q[1]),5,0,7);g.fill()},
   right(t){const{g,w,h}=fit(api.cr),KM=etr.length-1;let ym=.1;for(let k=1;k<=KM;k++)ym=Math.max(ym,etr[k],ete[k]||0);const P=plot(g,w,h,[0,KM+1],[0,ym*1.15],t,{xstep:5,xlabel:'k'});g.font=MONO;g.fillStyle=t.muted;g.textAlign='right';[.1,.2,.3,.4,.5].forEach(v=>{if(v<ym*1.15){g.strokeStyle=t.line;g.beginPath();g.moveTo(P.m.l,P.Y(v));g.lineTo(w-P.m.r,P.Y(v));g.stroke();g.fillText((100*v)+'%',P.m.l-4,P.Y(v)+4)}});clipPlot(g,P);
    g.strokeStyle=mix(t.gold,t.gold,0,.5);g.lineWidth=9;g.beginPath();g.moveTo(P.X(S.k),P.Y(0));g.lineTo(P.X(S.k),P.Y(ym*1.15));g.stroke();[[etr,t.accent],[ete,t.ok]].forEach(([E,cl])=>{g.strokeStyle=cl;g.lineWidth=2.4;g.beginPath();for(let k=1;k<=KM;k++)k>1?g.lineTo(P.X(k),P.Y(E[k])):g.moveTo(P.X(k),P.Y(E[k]));g.stroke()});g.restore();
    g.textAlign='left';g.fillStyle=t.accent;g.fillText('train error',P.m.l+46,P.m.t+8);g.fillStyle=t.ok;g.fillText('test error',P.m.l+46,P.m.t+23)},
   read(set){const q=api.probe,nb=near(q[0],q[1],S.k),b=nb.reduce((s,n)=>s+n[1].c,0);let bk=1;for(let k=2;k<ete.length;k++)if(ete[k]<ete[bk])bk=k;set('k',String(S.k));set('vote',(nb.length-b)+' for A, '+b+' for B');set('bk',String(bk))}}}}),

clfLesson({id:'nbayes',still:'Training is one pass of arithmetic with no iterations: two averages and two variances per class, and the share of each class.',steps:['Split the training points by class.','For each class and each feature, compute the mean and the variance. That gives one bell curve per feature.','Record what share of the points each class has (the prior).','To predict: for each class, multiply the prior by the heights of its bell curves at the new point. The larger product wins.'],tab:'Naive Bayes',title:'One feature at a time',ds:['blobs','overlap','moons'],play:'Sweep the correlation',S:{corr:0},
 lede:'Describe each class by a bell curve for each feature separately, and pretend the features have nothing to do with each other. It is a crude picture of the data and it often classifies well anyway. Make the features correlated and watch where the pretence starts to cost.',
 capR:'What the model stores: one bell curve per feature, per class',ctl:`<p style="margin:0;font-size:.9rem;color:var(--muted)">Nothing to tune. The model is four means, four variances and the two class shares.</p>`,
 dataCtl:slider('nbayes-corr','How strongly the two features move together',-.92,.92,.01,0),reads:rd('q','Test accuracy if the correlation were modelled')+rd('pr','Share of class B (the prior)'),
 tryit:'With the correlation at 0 the dashed ellipses match the clouds. Slide it to 0.9: the clouds tilt but the ellipses cannot. Compare the test accuracy with the one from a model that does allow for correlation.',
 math:String.raw`<h4>Intuition</h4><p>A doctor reasons backwards: given these symptoms, which illness is likely? But what is easy to learn from records runs forwards: given the illness, how common is each symptom? Bayes' rule turns one into the other. The "naive" part is a shortcut: treat each symptom as if it told you something independent of the others, so the evidence simply multiplies. That is rarely true, and the method works surprisingly often regardless.</p>
 <h4>Bayes' rule for classes</h4>$$P(c\mid\mathbf x)=\frac{P(c)\,p(\mathbf x\mid c)}{\sum_{c'}P(c')\,p(\mathbf x\mid c')}$$<p>\(P(c)\) is the prior, the share of each class. \(p(\mathbf x\mid c)\) says what the features of class \(c\) look like. A classifier built this way is called <b>generative</b>: it models how each class produces data. Logistic regression is <b>discriminative</b>: it models only the boundary.</p>
 <h4>The naive assumption</h4>$$p(\mathbf x\mid c)=\prod_{j=1}^{d}p(x_j\mid c)$$<p>Within a class, the features are taken to be independent. With Gaussian features each factor is a one-dimensional bell curve, the four curves on the right:</p>$$p(x_j\mid c)=N\big(x_j;\ \mu_{jc},\ \sigma^2_{jc}\big).$$<p>In terms of the Gaussian module this is a diagonal covariance matrix per class: ellipses that can stretch along the axes but never tilt.</p>
 <h4>Why make such an assumption</h4><p>A full description of \(d\) features needs on the order of \(d^2\) numbers per class; the naive one needs \(2d\), each estimated from a one-dimensional histogram. With thousands of features and little data (words in an email, say) the full model cannot be estimated at all and the naive one can. Training is a single pass of counting.</p>
 <h4>What goes wrong</h4><p>Correlated features are counted as separate pieces of evidence when they are really the same evidence twice. The probabilities become overconfident, pushed toward 0 and 1. The decision often stays right even so, because only the ranking of the classes matters for the decision.</p>`,
 q:'Naive Bayes says 99.9% for a spam email. Should you believe the number?',a:'Believe the decision more than the number. When features are correlated the same evidence is multiplied in several times, so the probabilities are pushed to the extremes. The email is probably spam, but the true probability is likely well below 99.9%.',
 setup(api){const S=api.S;let G=[],pr=.5,cs,tk;const nb=(k,x,y)=>-.5*Math.log(G[k].a*G[k].d)-.5*((x-G[k].mx)**2/G[k].a+(y-G[k].my)**2/G[k].d);
  cs=api.bind('corr','corr',f2,()=>api.regen());tk=sweepTick(()=>S.corr,v=>{S.corr=v;cs.set(v);api.regen()},-.9,.9,9);
  return{fit(){const T=api.train;G=[gfit(T,0),gfit(T,1)];pr=G[1].n/Math.max(1,T.length)},p:(x,y)=>sig(Math.log(pr/(1-pr)+1e-12)+nb(1,x,y)-nb(0,x,y)),tick(){tk();return false},
   overlay(g,X,Y,t){[t.accent,t.cut].forEach((cl,k)=>{g.setLineDash([6,4]);g.strokeStyle=cl;g.lineWidth=2;[1,2].forEach(r=>{ellPath(g,X,Y,G[k].mx,G[k].my,G[k].a,0,G[k].d,r);g.stroke()});g.setLineDash([])})},
   right(t){const{g,w,h}=fit(api.cr),hh=h/2;[['x',k=>[G[k].mx,Math.sqrt(G[k].a)]],['y',k=>[G[k].my,Math.sqrt(G[k].d)]]].forEach(([nm,fn],r)=>{g.save();g.translate(0,r*hh);let ym=0;[0,1].forEach(k=>{ym=Math.max(ym,npdf(0,0,fn(k)[1]))});const P=plot(g,w,hh,[-3,3],[0,ym*1.2],t,{xlabel:'feature '+nm});clipPlot(g,P);
     [t.accent,t.gold].forEach((cl,k)=>{const a=fn(k);area(g,P,x=>npdf(x,a[0],a[1]),-3,3);g.fillStyle=mix(cl,cl,0,.22);g.fill();curve(g,P,x=>npdf(x,a[0],a[1]),-3,3);g.strokeStyle=cl;g.lineWidth=2.4;g.stroke()});g.restore();g.restore()})},
   read(set){const te=api.test,T=api.train,Q=[gfit(T,0),gfit(T,1)],ok=te.filter(p=>((Math.log(pr/(1-pr)+1e-12)+glog(Q[1],p.x,p.y)-glog(Q[0],p.x,p.y))>=0?1:0)===p.c).length;set('q',te.length?(100*ok/te.length).toFixed(1)+'%':'–');set('pr',(100*pr).toFixed(0)+'%')}}}}),

clfLesson({id:'lda',still:'Training is one pass of arithmetic with no iterations: a mean per class and a covariance, shared (LDA) or one per class (QDA).',steps:['Split the training points by class and compute each class’s mean.','Compute the covariance of each class. For LDA, average them into one shared covariance.','Record the share of each class (the prior).','To predict: evaluate each class’s Gaussian at the new point, times its prior. The taller one wins.'],tab:'LDA and QDA',title:'One hill per class',ds:['blobs','overlap','moons','circles'],play:'Change the spread of class B',r3d:true,S:{kind:'lda',sb:1,corr:.5},
 lede:'Fit a Gaussian hill to each class and assign every point to the taller hill. If the hills are forced to have the same shape, the line where they cross is straight (LDA). If each keeps its own shape, the crossing is a curve (QDA).',
 capR:'The two fitted hills: each point goes to the taller one',ctl:`<div class="row seg" id="lda-kind"><button class="btn" type="button" data-k="lda">LDA: One Shared Shape</button><button class="btn" type="button" data-k="qda">QDA: A Shape per Class</button></div>`,
 dataCtl:slider('lda-sb','Spread of class B, relative to A',.4,2.4,.02,1)+slider('lda-corr','Tilt of the clouds',-.9,.9,.01,.5),reads:rd('np','Numbers the model had to estimate','hl')+rd('ot','Test accuracy of the other method'),
 tryit:'With equal spreads LDA and QDA give nearly the same boundary. Make class B much more spread out than A and switch between the two. Then try the ring around a core: which one can handle it, and why?',
 math:String.raw`<h4>Intuition</h4><p>In the Gaussian module you fitted one hill to a cloud of points. Now fit one hill to each class. A new point belongs to whichever class's hill is higher above it, after weighting each hill by how common the class is. The boundary is the line on the ground directly below where the two hills cross. Whether that line is straight or curved depends on one decision: must the hills have the same shape?</p>
 <h4>The model</h4>$$p(\mathbf x\mid c)=N(\mathbf x;\ \boldsymbol\mu_c,\ \Sigma_c),\qquad \hat y=\arg\max_c\ \delta_c(\mathbf x),\qquad \delta_c(\mathbf x)=\ln\pi_c+\ln p(\mathbf x\mid c)$$<p>with \(\pi_c\) the class share. It is Naive Bayes without the naive assumption: the covariance is allowed to tilt.</p>
 <h4>QDA: each class has its own covariance</h4>$$\delta_c(\mathbf x)=\ln\pi_c-\tfrac12\ln|\Sigma_c|-\tfrac12(\mathbf x-\boldsymbol\mu_c)^{\top}\Sigma_c^{-1}(\mathbf x-\boldsymbol\mu_c)$$<p>Setting \(\delta_A=\delta_B\) leaves terms in \(\mathbf x^{\top}(\Sigma_A^{-1}-\Sigma_B^{-1})\mathbf x\): a quadratic. The boundary is a conic: an ellipse, parabola or hyperbola. A tight class surrounded by a wide one gets a closed curve around it.</p>
 <h4>LDA: one covariance shared by all</h4><p>If \(\Sigma_A=\Sigma_B=\Sigma\), the quadratic terms cancel and what remains is linear in \(\mathbf x\):</p>$$\delta_c(\mathbf x)=\mathbf x^{\top}\Sigma^{-1}\boldsymbol\mu_c-\tfrac12\boldsymbol\mu_c^{\top}\Sigma^{-1}\boldsymbol\mu_c+\ln\pi_c$$<p>The boundary is a straight line, perpendicular to \(\Sigma^{-1}(\boldsymbol\mu_B-\boldsymbol\mu_A)\). Equivalently: assign each point to the class whose mean is nearest in Mahalanobis distance. \(\Sigma\) is estimated by pooling both classes.</p>
 <h4>Which to use</h4><p>In \(d\) dimensions with \(K\) classes, LDA estimates one covariance (\(d(d+1)/2\) numbers), QDA \(K\) of them. QDA is more flexible and needs more data; LDA is stiffer and steadier. It is the bias–variance trade again. LDA and logistic regression both give straight boundaries; LDA assumes Gaussian classes and is more efficient when that is true, logistic regression assumes less and is safer when it is not.</p>`,
 q:'LDA and logistic regression both draw a straight line. When would they give different lines?',a:'When the classes are not Gaussian with equal covariance, for example when there are outliers far from the boundary. LDA uses every point to estimate means and covariance, so distant points move the line. Logistic regression is driven mainly by points near the boundary and is less affected.',
 setup(api){const S=api.S,root=api.root;let G=[],Gd=[],pr=.5,ss,tk;const orb=Orbit(api.cr,()=>api.redraw(),root.querySelector('.viewbar'),{az:-.5,el:.6,zoom:1});
  ss=api.bind('sb','sb',f2,()=>api.regen());api.bind('corr','corr',f2,()=>api.regen());tk=sweepTick(()=>S.sb,v=>{S.sb=v;ss.set(v);api.regen()},.45,2.3,9);
  $('#lda-kind',root).addEventListener('click',e=>{const k=e.target.dataset&&e.target.dataset.k;if(k){S.kind=k;api.refit()}});
  const model=kind=>{const T=api.train,A=gfit(T,0),B=gfit(T,1);if(kind==='lda'){const n=A.n+B.n||1,a=(A.n*A.a+B.n*B.a)/n,b=(A.n*A.b+B.n*B.b)/n,d=(A.n*A.d+B.n*B.d)/n;return[{...A,a,b,d},{...B,a,b,d}]}return[A,B]},sc=(Q,x,y)=>Math.log(pr/(1-pr)+1e-12)+glog(Q[1],x,y)-glog(Q[0],x,y);
  return{fit(){const T=api.train;pr=clamp(T.filter(p=>p.c).length/Math.max(1,T.length),.01,.99);G=model(S.kind);Gd=model(S.kind==='lda'?'qda':'lda')},p:(x,y)=>sig(sc(G,x,y)),tick(){tk();return false},start(){orb.spin(true)},stop(){orb.spin(false)},
   overlay(g,X,Y,t){[t.accent,t.cut].forEach((cl,k)=>{g.setLineDash([6,4]);g.strokeStyle=cl;g.lineWidth=2;[1,2].forEach(r=>{ellPath(g,X,Y,G[k].mx,G[k].my,G[k].a,G[k].b,G[k].d,r);g.stroke()});g.setLineDash([])})},
   right(t){const{g,w,h}=fit(api.cr),pr3=orb.cam(w,h,8.6),N=34,R=3,den=(k,x,y)=>(k?pr:1-pr)*Math.exp(glog(G[k],x,y))/(2*Math.PI);let mx=1e-9;const Z=[],Pp=[],Wn=[];
    for(let i=0;i<=N;i++){Z.push([]);Wn.push([]);for(let j=0;j<=N;j++){const x=-R+2*R*i/N,y=-R+2*R*j/N,a=den(0,x,y),b=den(1,x,y);Z[i].push(Math.max(a,b));Wn[i].push(b>a?1:0);mx=Math.max(mx,a,b)}}
    for(let i=0;i<=N;i++){Pp.push([]);for(let j=0;j<=N;j++)Pp[i].push(pr3(-R+2*R*i/N,-R+2*R*j/N,2.6*Z[i][j]/mx-.9))}const Q=[];for(let i=0;i<N;i++)for(let j=0;j<N;j++)Q.push({i,j,d:(Pp[i][j][2]+Pp[i+1][j+1][2])/2});Q.sort((a,b)=>b.d-a.d);g.lineWidth=.6;
    for(const q of Q){const z=(Z[q.i][q.j]+Z[q.i+1][q.j+1])/(2*mx),cl=Wn[q.i][q.j]?t.gold:t.accent;g.beginPath();g.moveTo(Pp[q.i][q.j][0],Pp[q.i][q.j][1]);g.lineTo(Pp[q.i+1][q.j][0],Pp[q.i+1][q.j][1]);g.lineTo(Pp[q.i+1][q.j+1][0],Pp[q.i+1][q.j+1][1]);g.lineTo(Pp[q.i][q.j+1][0],Pp[q.i][q.j+1][1]);g.closePath();g.fillStyle=mix(t.bg,cl,.18+.82*Math.pow(z,.6));g.fill();g.strokeStyle=mix(t.ink,t.ink,0,.14);g.stroke()}},
   read(set){const te=api.test,ok=te.filter(p=>(sc(Gd,p.x,p.y)>=0?1:0)===p.c).length;set('np',S.kind==='lda'?'4 means + 3 shared = 7':'4 means + 3 + 3 = 10');set('ot',(S.kind==='lda'?'QDA: ':'LDA: ')+(te.length?(100*ok/te.length).toFixed(1)+'%':'–'));
    root.querySelectorAll('#lda-kind button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.k===S.kind?'true':'false'))}}}}),

clfLesson({id:'perceptron',maxWhat:'passes',hard:true,steps:['Start with a random line.','Take the next training point and check which side of the line it is on.','If it is on the correct side, change nothing.','If it is on the wrong side, add η × (±1) × the point to the weights. The line swings toward it.','After a full pass with no mistakes, stop.'],tab:'Perceptron',title:'Learning from mistakes',ds:['blobs','overlap','moons','xor'],play:'Train',stepBtn:true,S:{lr:.5},n:60,
 lede:'Start with any line. Visit the points one at a time. If a point is on the right side, do nothing. If it is on the wrong side, swing the line toward it. Repeat. When a straight line can separate the classes this always finishes. When none can, it never does.',
 capR:'Mistakes in each pass through the data',ctl:slider('perceptron-lr','Size of each correction η',.05,2,.05,.5),reads:rd('ep','Passes through the data')+rd('up','Corrections made','hl')+rd('ms','Mistakes in the last full pass','hl2'),
 tryit:'On the two clouds, count the passes until a pass has no mistakes. Then choose the overlapping clouds or the checkerboard and let it run: does the mistake count ever reach zero? Drag one point across to the other side of the line and train again.',
 math:String.raw`<h4>Intuition</h4><p>This is the oldest learning algorithm, from 1958, and the simplest picture of what learning from examples means. The model makes a guess. If the guess is right, leave everything alone. If it is wrong, nudge the weights so that this example would have come out a little more right. That is all. A single artificial neuron with this rule is the ancestor of every neural network.</p>
 <h4>The model</h4>$$\hat y=\operatorname{sign}\big(\mathbf w^{\top}\mathbf x+b\big),\qquad y\in\{-1,+1\}$$<p>A hard yes or no: which side of the line \(\mathbf w^{\top}\mathbf x+b=0\) the point falls on. The vector \(\mathbf w\) points across the line toward the positive side.</p>
 <h4>The update</h4><p>For each point in turn, if it is misclassified, meaning \(y_i(\mathbf w^{\top}\mathbf x_i+b)\le0\):</p>$$\mathbf w\leftarrow\mathbf w+\eta\,y_i\,\mathbf x_i,\qquad b\leftarrow b+\eta\,y_i$$<p>Adding \(y_i\mathbf x_i\) rotates \(\mathbf w\) toward a positive point or away from a negative one. After the update that point's score \(y_i\mathbf w^{\top}\mathbf x_i\) has gone up by \(\eta\lVert\mathbf x_i\rVert^2\): it is closer to being right, though not necessarily right yet.</p>
 <h4>The convergence theorem</h4><p>If some line separates the classes with margin \(\gamma\), and all points lie within radius \(R\), the perceptron makes at most</p>$$\Big(\frac{R}{\gamma}\Big)^2\ \text{ corrections}$$<p>and then stops, whatever the order of the points. A wide gap between the classes means few mistakes.</p>
 <h4>Its limits</h4><p>If no separating line exists, the updates never stop: the line keeps swinging as different points take turns being wrong. The checkerboard (XOR) is the famous example; the proof in 1969 that a single perceptron cannot solve it stalled neural network research for a decade, until hidden layers were shown to fix it. And when the data is separable, the perceptron stops at the first line that works, which may pass very close to some points. Choosing the best such line is the idea of the support vector machine.</p>`,
 q:'Two runs on the same separable data end with different lines. Is one of them wrong?',a:'Neither is wrong by the perceptron’s own standard: both separate the training data, and it stops as soon as that happens. Which line it reaches depends on the starting weights and the order of the points. They may differ in how well they generalise, which is the motivation for maximising the margin.',
 setup(api){const S=api.S;let w,order,i,ep,mist,hist,last,upd,wait=0,fr=0,msg='',cu=0;const newEp=()=>{order=api.train.slice();for(let a=order.length-1;a>0;a--){const b=Math.floor(Math.random()*(a+1));[order[a],order[b]]=[order[b],order[a]]}i=0;mist=0};
  const reset=()=>{w=[0,Math.random()-.5,Math.random()-.5];ep=0;hist=[];upd=0;last=null;wait=0;newEp();api.note('');msg='A random starting line. Press Train or One step.';cu=0};
  const adv=()=>{while(i<order.length){const p=order[i++],y=p.c?1:-1;if(y*(w[0]+w[1]*p.x+w[2]*p.y)<=0){const o=w.slice();w[0]+=S.lr*y;w[1]+=S.lr*y*p.x;w[2]+=S.lr*y*p.y;mist++;upd++;last=p;cu=3;msg='Pass '+(ep+1)+', point '+i+' of '+order.length+': ('+f2(p.x)+', '+f2(p.y)+') is class '+(p.c?'B':'A')+' but lies on the '+(p.c?'A':'B')+' side. Wrong, so add '+f2(S.lr)+' × ('+(y>0?'+1':'−1')+') × (1, '+f2(p.x)+', '+f2(p.y)+') to the weights: ('+o.map(f2).join(', ')+') → ('+w.map(f2).join(', ')+'). Correction number '+upd+'.';return'upd'}}hist.push(mist);ep++;const done=mist===0;msg='Pass '+ep+' finished with '+mist+(mist===1?' mistake.':' mistakes.')+(done?' Every point is on the correct side, so the perceptron stops.':' Start the next pass.');cu=done?4:1;newEp();if(done)last=null;return done?'done':'epoch'};
  api.bind('lr','lr',f2,()=>{});
  return{reset,p:(x,y)=>sig(7*(w[0]+w[1]*x+w[2]*y)/(Math.hypot(w[1],w[2])||1)),stepOnce:()=>{adv()},count:()=>ep,done:()=>wait>0,tick(){fr++;if(wait>0)return false;if(fr%5)return false;const r=adv();if(r==='done'){api.note('A full pass with no mistakes: every training point is on the right side, so it stops.');wait=220}else if(ep>=40){api.note('40 passes and still making mistakes. No straight line separates these classes, so the perceptron will never stop.');wait=320}return true},
   overlay(g,X,Y,t){if(last){g.strokeStyle=t.ink;g.lineWidth=3;g.beginPath();g.arc(X(last.x),Y(last.y),11,0,7);g.stroke()}const n=Math.hypot(w[1],w[2])||1,cx=-w[0]*w[1]/(n*n),cy=-w[0]*w[2]/(n*n);if(Math.abs(cx)<2.8&&Math.abs(cy)<2.8){g.strokeStyle=t.ink;g.lineWidth=2;g.beginPath();g.moveTo(X(cx),Y(cy));g.lineTo(X(cx+.6*w[1]/n),Y(cy+.6*w[2]/n));g.stroke();g.font=MONO;g.fillStyle=t.ink;g.fillText('w',X(cx+.75*w[1]/n),Y(cy+.75*w[2]/n))}},
   right(t){const{g,w:cw,h}=fit(api.cr),n=Math.max(12,hist.length),mx=Math.max(4,...hist),P=plot(g,cw,h,[0,n+.5],[0,mx*1.1],t,{xstep:n>30?10:n>14?5:2,xlabel:'pass'});g.font=MONO;g.fillStyle=t.muted;g.textAlign='right';g.fillText(String(mx),P.m.l-6,P.Y(mx)+4);g.fillText('0',P.m.l-6,P.Y(0)+4);clipPlot(g,P);const bw=(P.X(1)-P.X(0))*.7;hist.forEach((v,k)=>{g.fillStyle=v?t.ok:t.accent;g.fillRect(P.X(k+1)-bw/2,P.Y(Math.max(v,mx*.012)),bw,P.Y(0)-P.Y(Math.max(v,mx*.012)))});g.restore()},
   status:()=>msg,cur:()=>cu,
   read(set){set('ep',String(ep));set('up',String(upd));set('ms',hist.length?String(hist[hist.length-1]):'–')}}}}),

clfLesson({id:'svm',maxWhat:'iterations',stepBtn:true,steps:['Start with a flat score, so the street is infinitely wide.','Find every point that is inside the street or on the wrong side (y·f(x) < 1).','Pull the line toward classifying those points better, by C × each of them.','At the same time shrink the weights slightly, which widens the street.','Repeat with smaller and smaller steps until the pull and the shrink balance.'],tab:'Support vector machines',title:'The widest street between the classes',ds:['blobs','overlap','moons'],play:'Train',S:{C:1},n:80,
 lede:'Many lines separate two clouds. The support vector machine picks the one in the middle of the widest possible street between them. Only the points on the kerbs of the street matter: move any other point and nothing changes.',
 capR:'How far each point is on the correct side, and what it costs',ctl:slider('svm-c','Cost of a violation, C (log scale)',-2,2,.05,0),reads:rd('mw','Width of the street','hl')+rd('sv','Support vectors (ringed)','hl2')+rd('hl','Total hinge loss'),
 tryit:'Drag a point that is far from the street: does the line move? Now drag one of the ringed points. Then lower C to 0.01 and raise it to 100 on the overlapping clouds: what happens to the width of the street and to the number of ringed points?',
 math:String.raw`<h4>Intuition</h4><p>The perceptron stops at any line that separates the classes. But a line that scrapes past a training point leaves no room for error: a new point slightly different from that one lands on the wrong side. Better to leave as much room as possible on both sides. Picture the boundary as the centre line of a street and widen the street until its kerbs touch the nearest points of each class. Those touching points hold the street in place, like supports; every other point could be removed without changing anything.</p>
 <h4>The margin</h4><p>With labels \(y_i=\pm1\) and \(f(\mathbf x)=\mathbf w^{\top}\mathbf x+b\), scale the weights so the kerbs are at \(f=\pm1\). The distance from the centre line to a kerb is \(1/\lVert\mathbf w\rVert\), so</p>$$\text{street width}=\frac{2}{\lVert\mathbf w\rVert}.$$<p>Widening the street means shrinking \(\lVert\mathbf w\rVert\).</p>
 <h4>Hard margin</h4>$$\min_{\mathbf w,b}\ \tfrac12\lVert\mathbf w\rVert^2\quad\text{subject to}\quad y_i\,f(\mathbf x_i)\ge1\ \text{ for all }i$$<p>Every point must be on its own side, outside the street. Possible only when the classes are separable.</p>
 <h4>Soft margin</h4>$$\min_{\mathbf w,b}\ \tfrac12\lVert\mathbf w\rVert^2+C\sum_{i=1}^n\max\big(0,\ 1-y_i\,f(\mathbf x_i)\big)$$<p>Allow points inside the street or on the wrong side, at a price. The price is the <b>hinge loss</b> on the right: zero for a point at or beyond its kerb (\(y_if\ge1\)), then rising in a straight line. \(C\) sets the exchange rate. Large \(C\): violations are expensive, the street is narrow and follows the data closely. Small \(C\): a wide street with many points inside it, a smoother and steadier boundary. \(1/C\) plays the role of \(\lambda\) in ridge regression.</p>
 <h4>Support vectors</h4><p>The solution has the form \(\mathbf w=\sum_i\alpha_iy_i\mathbf x_i\) with \(\alpha_i>0\) only for points on or inside the street. Points safely beyond their kerb have zero hinge loss and zero gradient: the model does not know they exist. Compare logistic regression, where every point always pulls a little.</p>
 <h4>What comes next</h4><p>The solution depends on the data only through inner products \(\mathbf x_i^{\top}\mathbf x_j\). Replacing those with a kernel gives curved boundaries at no extra cost. That is the next lesson.</p>`,
 q:'You delete half the training points, none of them support vectors. What happens to the boundary?',a:'Nothing. Points beyond the kerbs have zero hinge loss and contribute nothing to the solution, so removing them leaves the same optimum. Only the support vectors determine the line.',
 setup(api){const S=api.S;let w,t0,wait=0;const C=()=>Math.pow(10,S.C),f=p=>w[0]+w[1]*p.x+w[2]*p.y,reset=()=>{w=[0,.01,.01];t0=0;wait=0};
  const it=()=>{const T=api.train,g=[0,w[1],w[2]],c=C();for(const p of T){const y=p.c?1:-1;if(y*f(p)<1){g[0]-=c*y;g[1]-=c*y*p.x;g[2]-=c*y*p.y}}const lr=.25/(1+c*T.length)/(1+.003*t0);t0++;for(let j=0;j<3;j++)w[j]-=lr*g[j]};
  api.bind('c','C',v=>Math.pow(10,v)<10?Math.pow(10,v).toFixed(2):Math.pow(10,v).toFixed(0),()=>{reset();api.refit()});
  return{reset,fit(){for(let k=0;k<400;k++)it()},stepOnce(){for(let k=0;k<12;k++)it()},status(){const T=api.train;let sv=0;for(const p of T)if((p.c?1:-1)*f(p)<1)sv++;return'Iteration '+t0+': '+sv+' of '+T.length+' points are inside the street or on the wrong side, and only those pull on the line. The street is '+f2(2/(Math.hypot(w[1],w[2])||1e-9))+' wide. The line is '+f2(w[0])+' + '+f2(w[1])+'·x + '+f2(w[2])+'·y = 0.'+(wait>0?' The pull and the shrink are in balance: training is finished.':'')},cur(){return wait>0?4:2},p:(x,y)=>sig(2.2*(w[0]+w[1]*x+w[2]*y)),done:()=>wait>0,tick(){if(wait>0)return false;for(let k=0;k<12;k++)it();if(t0>2600)wait=200;return true},count:()=>t0,
   overlay(g,X,Y,t){g.setLineDash([6,5]);g.strokeStyle=t.ink;g.lineWidth=1.5;lineAt(g,X,Y,w,1);lineAt(g,X,Y,w,-1);g.setLineDash([]);g.strokeStyle=t.ink;g.lineWidth=2.4;for(const p of api.train){if((p.c?1:-1)*f(p)<=1.03){g.beginPath();g.arc(X(p.x),Y(p.y),9,0,7);g.stroke()}}},
   right(t){const{g,w:cw,h}=fit(api.cr),P=plot(g,cw,h,[-3,5],[0,4],t,{yticks:[1,2,3],xlabel:'y · f(x): distance on the correct side'});clipPlot(g,P);g.fillStyle=mix(t.ok,t.ok,0,.08);g.fillRect(P.X(-3),P.Y(4),P.X(1)-P.X(-3),P.Y(0)-P.Y(4));
    g.strokeStyle=t.ink;g.lineWidth=2.6;g.beginPath();g.moveTo(P.X(-3),P.Y(4));g.lineTo(P.X(1),P.Y(0));g.lineTo(P.X(5),P.Y(0));g.stroke();g.setLineDash([4,4]);g.strokeStyle=t.muted;g.lineWidth=1;[0,1].forEach(v=>{g.beginPath();g.moveTo(P.X(v),P.Y(0));g.lineTo(P.X(v),P.Y(4));g.stroke()});g.setLineDash([]);
    for(const p of api.train){const m=clamp((p.c?1:-1)*f(p),-2.95,4.95);g.fillStyle=p.c?t.gold:t.accent;g.beginPath();g.arc(P.X(m),P.Y(Math.max(0,1-m)),4,0,7);g.fill()}g.restore();g.font=MONO;g.fillStyle=t.muted;g.textAlign='center';g.fillText('wrong side',P.X(-1.5),P.m.t+8);g.fillText('in the street',P.X(.5),P.m.t+22);g.fillText('safe: costs nothing',P.X(3),P.m.t+8)},
   read(set){const T=api.train;let hl=0,sv=0;for(const p of T){const m=(p.c?1:-1)*f(p);hl+=Math.max(0,1-m);if(m<=1.03)sv++}set('mw',f2(2/(Math.hypot(w[1],w[2])||1e-9)));set('sv',sv+' of '+T.length);set('hl',f2(hl))}}}}),

clfLesson({id:'kernel',still:'Training here is ordinary logistic regression, run on three coordinates instead of two (or, for the RBF kernel, one linear solve for the bump weights). The lesson is in the lift, not the fitting.',steps:['Compute the new coordinate z for every training point.','Fit a linear classifier in the lifted space (x, y, z): a flat plane.','To predict for a new point, compute its z the same way and see which side of the plane it is on.','Seen from above, the plane’s edge is the curved boundary.'],tab:'The kernel trick',title:'Lift the data until a flat cut works',ds:['circles','xor','moons','blobs'],play:'Lift',r3d:true,S:{lift:'r2',gam:1},n:140,nc:46,
 lede:'No straight line separates a ring from its core. But add a third coordinate, the distance from the centre, and the core sinks below the ring. Now a flat plane slices them apart. Seen from above, that flat cut is a circle.',
 capL:'From above: the flat cut in 3D becomes a curved boundary in 2D',capR:'The same points with a third coordinate added (drag to rotate)',
 ctl:`<label class="ctl" for="kernel-lift"><span>Third coordinate</span><select id="kernel-lift"><option value="none">None: stay flat</option><option value="r2" selected>z = x² + y²</option><option value="xy">z = x · y</option><option value="bump">z = a bump at the centre</option><option value="kern">RBF kernel: a bump at every point</option></select></label>`+slider('kernel-gam','Width setting γ (RBF kernel only)',-1,1.3,.02,0),
 reads:rd('lin','Test accuracy of a straight line, no lift')+rd('what','What separates the classes','hl'),
 tryit:'Start with “None: stay flat” on the ring data and read the accuracy. Then choose z = x² + y² and watch the points rise. Rotate until you look along the plane. Switch to the checkerboard: which lift works there? Finally choose the RBF kernel and raise γ until the boundary wraps single points.',
 math:String.raw`<h4>Intuition</h4><p>Lay a red napkin flat on a table and scatter blue beads around it. No straight ruler laid on the table separates red from blue. Now pinch the napkin in the middle and lift: the red rises, the blue stays down, and a sheet of card slid in horizontally separates them perfectly. Nothing about the data changed. You gave it one more dimension to move in, and in the bigger space a simple flat cut was enough.</p>
 <h4>Lifting by hand</h4>$$\phi(x_1,x_2)=\big(x_1,\ x_2,\ x_1^2+x_2^2\big)$$<p>In the lifted space fit an ordinary linear classifier, a plane \(w_0+w_1x_1+w_2x_2+w_3z=0\). Back on the table that plane is the set where \(w_0+w_1x_1+w_2x_2+w_3(x_1^2+x_2^2)=0\): a circle. A linear method plus a nonlinear lift gives a nonlinear boundary. For the checkerboard, the right lift is \(z=x_1x_2\), positive in two opposite quadrants and negative in the other two.</p>
 <h4>The problem with lifting by hand</h4><p>You have to know which lift to use. You could add every product of features up to some degree, but the number of new coordinates explodes: degree 5 on 100 features is nearly a hundred million.</p>
 <h4>The trick</h4><p>Many linear methods (SVMs, ridge regression, PCA) only ever use the data through inner products \(\mathbf x_i^{\top}\mathbf x_j\). After lifting they would need \(\phi(\mathbf x_i)^{\top}\phi(\mathbf x_j)\). A <b>kernel</b> is a function that returns that number directly from the original points, without ever computing \(\phi\):</p>$$k(\mathbf a,\mathbf b)=\phi(\mathbf a)^{\top}\phi(\mathbf b)$$$$\text{polynomial: }\ k(\mathbf a,\mathbf b)=(1+\mathbf a^{\top}\mathbf b)^p\qquad\qquad \text{RBF: }\ k(\mathbf a,\mathbf b)=\exp\!\big(-\gamma\lVert\mathbf a-\mathbf b\rVert^2\big)$$<p>The polynomial kernel corresponds to all products of features up to degree \(p\), computed at the cost of one inner product. The RBF kernel corresponds to a lift into infinitely many dimensions.</p>
 <h4>What the model looks like</h4>$$f(\mathbf x)=\sum_{i=1}^n\alpha_i\,k(\mathbf x_i,\mathbf x)+b$$<p>A weighted sum of bumps, one centred on each training point (for an SVM, only on the support vectors). The last option draws this \(f\) as a surface: hills over one class, hollows over the other, and the boundary where it crosses zero. \(\gamma\) sets the width of each bump: small \(\gamma\) gives broad bumps and a smooth boundary, large \(\gamma\) gives narrow spikes and a boundary that wraps each point, which is overfitting.</p>`,
 q:'The RBF kernel lifts the data into infinitely many dimensions. Why does that not overfit hopelessly?',a:'Because the fit is regularised. The margin of an SVM, or the penalty in kernel ridge, limits how much the function may wiggle regardless of how many dimensions it lives in. The flexibility that matters is set by γ and the penalty, not by the dimension of the lifted space.',
 setup(api){const S=api.S,root=api.root;let w=[0,0,0,0],al=[],Tr=[],wl=[0,0,0],u=0,wait=0;const orb=Orbit(api.cr,()=>api.redraw(),root.querySelector('.viewbar'),{az:-.55,el:.36,zoom:1});
  const zf=(x,y)=>S.lift==='r2'?(x*x+y*y)/3.4:S.lift==='xy'?x*y/2.4:S.lift==='bump'?2.4*Math.exp(-(x*x+y*y)/1.6):0,gam=()=>Math.pow(10,S.gam);
  const logit=(F,T)=>{const v=F(0,0).map(()=>0);for(let k=0;k<700;k++){const g=v.map(()=>0);for(const p of T){const f=F(p.x,p.y),e=sig(dot(v,f))-p.c;for(let j=0;j<v.length;j++)g[j]+=e*f[j]}for(let j=0;j<v.length;j++)v[j]-=.6*(g[j]/T.length+(j?.002*v[j]:0))}return v};
  const kf=(x,y)=>{let s=0;const gm=gam();for(let i=0;i<Tr.length;i++)s+=al[i]*Math.exp(-gm*((Tr[i].x-x)**2+(Tr[i].y-y)**2));return s};
  $('#kernel-lift',root).onchange=e=>{S.lift=e.target.value;u=0;wait=0;api.refit()};api.bind('gam','gam',v=>Math.pow(10,v).toFixed(2));
  return{fit(){Tr=api.train;if(!Tr.length)return;wl=logit((x,y)=>[1,x,y],Tr);if(S.lift==='kern'){const n=Tr.length,gm=gam(),K=Tr.map((a,i)=>Tr.map((b,j)=>Math.exp(-gm*((a.x-b.x)**2+(a.y-b.y)**2))+(i===j?.15:0)));al=solve(K,Tr.map(p=>p.c?1:-1))}else w=S.lift==='none'?[...wl,0]:logit((x,y)=>[1,x,y,zf(x,y)],Tr)},
   p:(x,y)=>S.lift==='kern'?sig(3.5*kf(x,y)):sig(w[0]+w[1]*x+w[2]*y+w[3]*zf(x,y)),tick(){if(wait>0){wait--;if(!wait)u=0;return true}u=Math.min(1,u+.007);if(u>=1)wait=260;return true},start(){orb.spin(true)},stop(){orb.spin(false)},
   right(t){const{g,w:cw,h}=fit(api.cr),pr=orb.cam(cw,h,8.4),R=3,e=u<.5?2*u*u:1-2*(1-u)*(1-u),kern=S.lift==='kern',hz=(x,y)=>kern?clamp(kf(x,y),-1.6,1.6)*e:zf(x,y)*e,path=ps=>{g.beginPath();ps.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]))};
    g.strokeStyle=t.line;g.lineWidth=1;for(let k=-3;k<=3;k++){path([pr(k,-R,0),pr(k,R,0)]);g.stroke();path([pr(-R,k,0),pr(R,k,0)]);g.stroke()}
    const N=kern?26:16,Q=[];for(let i=0;i<N;i++)for(let j=0;j<N;j++){const a0=-R+2*R*i/N,a1=-R+2*R*(i+1)/N,b0=-R+2*R*j/N,b1=-R+2*R*(j+1)/N,z=hz((a0+a1)/2,(b0+b1)/2),ps=[pr(a0,b0,hz(a0,b0)),pr(a1,b0,hz(a1,b0)),pr(a1,b1,hz(a1,b1)),pr(a0,b1,hz(a0,b1))];Q.push({ps,z,d:(ps[0][2]+ps[2][2])/2})}Q.sort((a,b)=>b.d-a.d);
    for(const q of Q){path(q.ps);g.closePath();if(kern){g.fillStyle=mix(q.z>=0?t.gold:t.accent,t.bg,.35,.55);g.fill()}g.strokeStyle=mix(t.ink,t.ink,0,.16);g.lineWidth=.7;g.stroke()}
    const zp=(x,y)=>kern?0:Math.abs(w[3])>1e-6?-(w[0]+w[1]*x+w[2]*y)/w[3]:NaN,pa=clamp((e-.72)/.28,0,1);
    if(pa>0&&(kern||isFinite(zp(0,0)))){const M2=8;for(let i=0;i<M2;i++)for(let j=0;j<M2;j++){const a0=-R+2*R*i/M2,a1=-R+2*R*(i+1)/M2,b0=-R+2*R*j/M2,b1=-R+2*R*(j+1)/M2,zs=[zp(a0,b0),zp(a1,b0),zp(a1,b1),zp(a0,b1)];if(zs.some(v=>v<-1.8||v>3.4))continue;path([pr(a0,b0,zs[0]),pr(a1,b0,zs[1]),pr(a1,b1,zs[2]),pr(a0,b1,zs[3])]);g.closePath();g.fillStyle=mix(t.ok,t.ok,0,.2*pa);g.fill();g.strokeStyle=mix(t.ok,t.ok,0,.5*pa);g.lineWidth=1;g.stroke()}}
    api.pts.map(p=>({p,q:pr(p.x,p.y,hz(p.x,p.y)+.03)})).sort((a,b)=>b.q[2]-a.q[2]).forEach(o=>{g.fillStyle=o.p.c?t.gold:t.accent;g.strokeStyle=t.bg;g.lineWidth=1;g.beginPath();g.arc(o.q[0],o.q[1],4,0,7);g.fill();g.stroke()});
    g.font=MONO;g.fillStyle=t.ok;g.textAlign='left';if(pa>0)g.fillText(kern?'burgundy sheet: height zero, the boundary':'burgundy sheet: the flat cut',8,14)},
   read(set){const te=api.test,ok=te.filter(p=>(wl[0]+wl[1]*p.x+wl[2]*p.y>=0?1:0)===p.c).length;set('lin',te.length?(100*ok/te.length).toFixed(1)+'%':'–');set('what',S.lift==='none'?'A line (no lift)':S.lift==='kern'?'Where a sum of '+Tr.length+' bumps crosses zero':'A flat plane in 3D')}}}}),

clfLesson({id:'tree',fromZero:true,hard:true,steps:['Put all training points in one region.','For each region, try every feature and every cut point, and measure how much each cut lowers the impurity.','Make the best cut. The region becomes two.','Repeat inside each new region, until the depth limit or the minimum region size is reached.','To predict, follow the questions down to a region and answer with its majority class.','Then prune. Find the question whose removal adds the fewest training mistakes per region saved, and remove it with everything below it.','Keep pruning one question at a time. Choose the size that does best on held-out data.'],tab:'Decision trees',title:'Twenty questions',ds:['moons','blobs','overlap','circles','xor'],play:'Grow the tree',stepBtn:true,S:{depth:6,minleaf:1},n:160,nc:60,
 lede:'Ask one yes-or-no question about one feature, the question that best sorts the classes. Then ask the best question inside each half, and again. Every question cuts a region in two with a straight, axis-parallel line.',
 capR:'The questions, in the order they were asked',ctl:slider('tree-depth','Deepest chain of questions allowed',1,7,1,6)+slider('tree-minleaf','Fewest points allowed in a region',1,30,1,1)+`<div class="row"><button class="btn" id="tree-prune" type="button">Prune One Step</button><button class="btn" id="tree-full" type="button">Show the Full Tree</button></div>`,
 reads:rd('sp','Questions asked so far','hl')+rd('lv','Regions (leaves) now')+rd('bd','Depth with the lowest test error')+rd('bp','Leaves at the best test accuracy while pruning','hl2'),
 tryit:'Step through the first three questions and find each one as a line on the left. Let the tree grow to depth 6 and look for tiny regions around single points. Then press “Prune One Step” repeatedly and watch the test accuracy: at how many regions is it best? Try the checkerboard: can a depth-1 tree do anything with it?',
 math:String.raw`<h4>Intuition</h4><p>In the game of twenty questions a good player does not ask "is it a giraffe?" first. They ask the question that splits the remaining possibilities most evenly into those it rules in and those it rules out. A decision tree plays this game with data: at each step it searches every feature and every cut point for the single question whose two answers are each as pure in one class as possible. The result reads like a flowchart, which is why trees are the easiest model to explain to someone else.</p>
 <h4>Measuring impurity</h4><p>For a region where a fraction \(p\) of the points is class B:</p>$$\text{Gini}=2p(1-p),\qquad \text{entropy}=-p\log_2p-(1-p)\log_2(1-p)$$<p>Both are zero when the region is pure (\(p=0\) or \(1\)) and largest when it is evenly mixed (\(p=\tfrac12\)). Gini is the chance that two points drawn from the region have different labels.</p>
 <h4>Choosing a split</h4><p>A split "\(x_j\le s\)" sends \(n_L\) points left and \(n_R\) right. Its quality is the drop in weighted impurity:</p>$$\Delta=I(\text{parent})-\frac{n_L}{n}I(\text{left})-\frac{n_R}{n}I(\text{right})$$<p>Try every feature \(j\) and every threshold \(s\) between neighbouring data values, and take the largest \(\Delta\). Then repeat inside each child. This is a greedy search: each question is the best one right now, with no looking ahead. That is why a depth-1 tree fails on the checkerboard, where no single question helps and two together are perfect.</p>
 <h4>Predicting</h4><p>Follow the questions down to a leaf and answer with the majority class there; the class share in the leaf is the predicted probability. The model is a piecewise-constant function on boxes.</p>
 <h4>Stopping</h4><p>Left alone, the tree keeps splitting until every leaf is pure: zero training error and a region for every noisy point. Limits on depth and on the number of points per leaf are the regularisation; alternatively grow fully and prune back using a penalty on the number of leaves.</p>
 <h4>Pruning</h4><p>A better strategy than stopping early is to grow a large tree and then cut it back. Stopping early can miss a weak-looking question that opens the way to a very good one below it. For pruning, define the cost of a tree \(T\) as its training mistakes plus a charge for every leaf:</p>$$R_\alpha(T)=R(T)+\alpha\,|T|$$<p>where \(R(T)\) is the number of misclassified training points and \(|T|\) the number of leaves. For any internal node \(t\), collapsing the subtree \(T_t\) below it into a single leaf adds \(R(t)-R(T_t)\) mistakes and saves \(|T_t|-1\) leaves. The ratio</p>$$g(t)=\frac{R(t)-R(T_t)}{|T_t|-1}$$<p>is the number of extra mistakes per leaf saved: the price of keeping that branch. <b>Weakest-link pruning</b> repeatedly removes the node with the smallest \(g(t)\). This produces a nested sequence of smaller and smaller trees, one for each range of \(\alpha\), ending at the root alone. Training accuracy can only fall along the way. Test accuracy typically rises first, as branches that fitted noise are removed, and then falls as real structure goes. Choose the tree in the sequence that does best on held-out data or in cross-validation.</p>
 <h4>Strengths and weaknesses</h4><p>No feature scaling needed, handles mixed feature types, finds interactions on its own, easy to read. But boundaries are staircases, so a diagonal edge takes many splits; and trees are unstable: a small change in the data can change the first question and with it everything below. Averaging many trees fixes the instability, which is the idea of random forests and boosting.</p>`,
 q:'A tree splits first on x at 0.4. You add three new data points and now it splits first on y. What does this tell you?',a:'Trees have high variance. Two different first questions were nearly equally good, and a small change in the data tipped the choice, which changes the whole tree below it. Predictions may be similar, but the structure is not stable. Averaging many trees grown on resampled data removes most of this.',
 setup(api){const S=api.S;let root=null,nsp=0,shown=0,wait=0,fr=0,bd=1,fresh=true,phase='grow',pmsg='',ph=[];const op=nd=>!!(nd.sp&&nd.sp.ord<shown&&!nd.cut);const gini=(n,n1)=>n?2*(n1/n)*(1-n1/n):0;
  const build=(T,D,ML)=>{const mk=(P,dp,box)=>({P,n:P.length,n1:P.filter(p=>p.c).length,dp,box,sp:null}),rt=mk(T,0,[-3,3,-3,3]),q=[rt];let ord=0;
   while(q.length){const nd=q.shift();if(nd.dp>=D||nd.n1===0||nd.n1===nd.n||nd.n<2*ML)continue;let best=null;const I=gini(nd.n,nd.n1);
    for(const f of['x','y']){const s=nd.P.slice().sort((a,b)=>a[f]-b[f]);let l1=0;for(let i=1;i<s.length;i++){l1+=s[i-1].c;if(s[i][f]===s[i-1][f]||i<ML||s.length-i<ML)continue;const r1=nd.n1-l1,gn=I-(i/nd.n)*gini(i,l1)-((nd.n-i)/nd.n)*gini(nd.n-i,r1);if(!best||gn>best.gn)best={gn,f,thr:(s[i][f]+s[i-1][f])/2,i,s}}}
    if(!best||best.gn<=1e-9&&nd.dp>0)continue;const b=nd.box,L=mk(best.s.slice(0,best.i),nd.dp+1,best.f==='x'?[b[0],best.thr,b[2],b[3]]:[b[0],b[1],b[2],best.thr]),Rr=mk(best.s.slice(best.i),nd.dp+1,best.f==='x'?[best.thr,b[1],b[2],b[3]]:[b[0],b[1],best.thr,b[3]]);nd.sp={f:best.f,thr:best.thr,gn:best.gn,ord:ord++,L,R:Rr};q.push(L,Rr)}return{rt,n:ord}};
  const leaf=(rt,x,y,lim)=>{let nd=rt;while(nd.sp&&nd.sp.ord<lim&&!nd.cut)nd=(nd.sp.f==='x'?x:y)<=nd.sp.thr?nd.sp.L:nd.sp.R;return nd};
  const accOf=P=>P.length?P.filter(p=>{const l=leaf(root,p.x,p.y,shown);return(l.n1/l.n>=.5?1:0)===p.c}).length/P.length:NaN;
  const prune=()=>{if(!root)return false;shown=nsp;let best=null;const info=nd=>{if(!op(nd))return{L:1,R:Math.min(nd.n1,nd.n-nd.n1)};const a=info(nd.sp.L),b=info(nd.sp.R),L=a.L+b.L,R=a.R+b.R,gq=(Math.min(nd.n1,nd.n-nd.n1)-R)/(L-1);if(!best||gq<best.g-1e-12||(Math.abs(gq-best.g)<1e-12&&L<best.L))best={nd,g:gq,L,add:Math.min(nd.n1,nd.n-nd.n1)-R};return{L,R}};const tot=info(root);if(!best)return false;
   if(!ph.length)ph.push({L:tot.L,te:accOf(api.test)});best.nd.cut=true;phase='prune';const left=tot.L-best.L+1,te=accOf(api.test);ph.push({L:left,te});
   pmsg='Pruning step '+(ph.length-1)+': removed the question “'+best.nd.sp.f+' ≤ '+best.nd.sp.thr.toFixed(2)+'” and '+(best.L>2?'the '+(best.L-2)+' below it':'nothing below it')+'. That merges '+best.L+' regions into one and adds '+best.add+(best.add===1?' training mistake':' training mistakes')+', the cheapest cut available ('+best.g.toFixed(2)+' mistakes per region saved). The tree now has '+left+(left===1?' region':' regions')+'. Train accuracy '+pct(accOf(api.train))+', test accuracy '+pct(te)+'.';return true};
  const dsl=api.bind('depth','depth',v=>String(v),()=>{api.refit()});api.bind('minleaf','minleaf',v=>String(v));
  $('#tree-prune',api.root).onclick=()=>{api.pause();if(!prune())api.note('Nothing is left to prune: the tree is a single region. Press Start over or Show the Full Tree.');else api.note('');api.redraw()};$('#tree-full',api.root).onclick=()=>{api.pause();api.note('');const un=nd=>{nd.cut=false;if(nd.sp){un(nd.sp.L);un(nd.sp.R)}};if(root)un(root);shown=nsp;phase='grow';pmsg='';ph=[];api.redraw()};
  return{fit(){const T=api.train,te=api.test;if(!T.length)return;const b=build(T,S.depth,S.minleaf);root=b.rt;nsp=b.n;phase='grow';pmsg='';ph=[];if(fresh){shown=nsp;fresh=false}else shown=Math.min(shown,nsp);let be=-1;bd=1;for(let d=1;d<=7;d++){const r=build(T,d,S.minleaf),ok=te.filter(p=>{const l=leaf(r.rt,p.x,p.y,1e9);return(l.n1/l.n>=.5?1:0)===p.c}).length;if(ok>be){be=ok;bd=d}}},
   reset(){shown=0;wait=0;phase='grow';pmsg='';ph=[];const un=nd=>{nd.cut=false;if(nd.sp){un(nd.sp.L);un(nd.sp.R)}};if(root)un(root)},p:(x,y)=>{if(!root)return.5;const l=leaf(root,x,y,shown);return l.n?clamp(l.n1/l.n,.02,.98)*.999+(l.n1*2===l.n?1e-4:0):.5},stepOnce(){if(phase==='prune'){if(!prune())this.reset()}else if(shown<nsp)shown++;else prune()},
   done:()=>wait>0,tick(){fr++;if(wait>0)return false;if(fr%38)return false;if(phase==='grow'&&shown<nsp)shown++;else if(!prune()){wait=260}return true},
   overlay(g,X,Y,t){const walk=nd=>{if(!op(nd))return;const b=nd.box,s=nd.sp;g.strokeStyle=t.ink;g.lineWidth=s.ord===shown-1?3.4:1.4;g.beginPath();if(s.f==='x'){g.moveTo(X(s.thr),Y(b[2]));g.lineTo(X(s.thr),Y(b[3]))}else{g.moveTo(X(b[0]),Y(s.thr));g.lineTo(X(b[1]),Y(s.thr))}g.stroke();walk(s.L);walk(s.R)};if(root)walk(root)},
   right(t){const{g,w,h}=fit(api.cr);if(!root)return;const leaves=[],lay=(nd,dp)=>{nd._d=dp;if(op(nd)){lay(nd.sp.L,dp+1);lay(nd.sp.R,dp+1);nd._x=(nd.sp.L._x+nd.sp.R._x)/2}else{nd._x=leaves.length;leaves.push(nd)}};lay(root,0);let md=0;const all=[],col=nd=>{all.push(nd);md=Math.max(md,nd._d);if(op(nd)){col(nd.sp.L);col(nd.sp.R)}};col(root);
    const X=v=>56+(leaves.length>1?v/(leaves.length-1):.5)*(w-112),Y=d=>26+(md?d/md:0)*(h-64),small=leaves.length>14;g.strokeStyle=t.muted;g.lineWidth=1.2;for(const nd of all)if(op(nd)){[nd.sp.L,nd.sp.R].forEach(ch=>{g.beginPath();g.moveTo(X(nd._x),Y(nd._d));g.lineTo(X(ch._x),Y(ch._d));g.stroke()})}
    g.textAlign='center';for(const nd of all){const x=X(nd._x),y=Y(nd._d),inner=op(nd);if(inner){const tx=nd.sp.f+' ≤ '+nd.sp.thr.toFixed(1);g.font=small?'10px "JetBrains Mono",monospace':MONO;const tw=g.measureText(tx).width+10;g.fillStyle=t.bg;g.strokeStyle=nd.sp.ord===shown-1?t.ink:t.muted;g.lineWidth=nd.sp.ord===shown-1?2.4:1;g.beginPath();g.rect(x-tw/2,y-10,tw,20);g.fill();g.stroke();g.fillStyle=t.ink;g.fillText(tx,x,y+4)}
     else{const pb2=nd.n?nd.n1/nd.n:.5;g.fillStyle=mix(pb2>=.5?t.gold:t.accent,t.bg,1-Math.abs(pb2-.5)*2,1);g.strokeStyle=pb2>=.5?t.gold:t.accent;g.lineWidth=2;g.beginPath();g.arc(x,y,small?6:10,0,7);g.fill();g.stroke();if(!small){g.font=MONO;g.fillStyle=t.muted;g.fillText((nd.n-nd.n1)+' A · '+nd.n1+' B',x,y+25)}}}
    g.font=MONO;g.fillStyle=t.muted;g.textAlign='left';g.fillText('yes ↙   no ↘',8,12)},
   status(){if(!root)return'';if(phase==='prune'&&pmsg)return pmsg;if(!shown)return'All '+root.n+' training points are in one region: '+(root.n-root.n1)+' of class A and '+root.n1+' of class B. Press Grow the tree or One step.';let f=null;const find=nd=>{if(!nd.sp)return;if(nd.sp.ord===shown-1)f=nd;find(nd.sp.L);find(nd.sp.R)};find(root);if(!f)return'';const sp=f.sp;
    return'Question '+shown+' of '+nsp+': is '+sp.f+' ≤ '+sp.thr.toFixed(2)+'? Of every possible cut in this region of '+f.n+' points, this one lowers the impurity most (by '+sp.gn.toFixed(3)+'). Yes: '+(sp.L.n-sp.L.n1)+' A and '+sp.L.n1+' B. No: '+(sp.R.n-sp.R.n1)+' A and '+sp.R.n1+' B.'+(shown>=nsp?' No allowed cut is left: the tree is finished.':'')},cur(){return phase==='prune'?5:!shown?0:shown>=nsp?4:2},
   read(set){let lv=0;const cnt=nd=>{if(op(nd)){cnt(nd.sp.L);cnt(nd.sp.R)}else lv++};if(root)cnt(root);set('sp',shown+' of '+nsp);set('lv',String(lv));set('bd',String(bd));let bq=null;for(const q of ph)if(!bq||q.te>=bq.te)bq=q;set('bp',bq?bq.L+' (test '+pct(bq.te)+')':'prune to find out')}}}})
];
